/**
 * JG Investment Plus — Apps Script package generator.
 *
 * Writes the generated files of emails/apps-script/ from the repository
 * sources, so the Apps Script copy can never drift from the approved email:
 *
 *   Assets.gs                 ← emails/assets/* (base64, keyed by the LOCKED
 *                               CID names in cid-assets.mjs)
 *   JGIntroductionV2.html     ← emails/jg-introduction-v2.html (byte-identical)
 *   JGIntroductionV2Text.html ← emails/jg-introduction-v2.txt  (byte-identical)
 *
 * Code.gs, Index.html and appsscript.json are hand-written and not touched.
 * The base64 lives only in Apps Script source, where it becomes MIME inline
 * image parts; it never appears in the email HTML.
 *
 *   node emails/scripts/build-apps-script.mjs
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve, basename } from "node:path";
import { fileURLToPath } from "node:url";
import { CID_ASSETS, ASSET_DIR } from "./cid-assets.mjs";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
export const APPS_SCRIPT_DIR = "emails/apps-script";

/** MIME filename of an asset: the file name without the @2x density suffix. */
const mimeFilename = (file) => basename(file).replace("@2x", "");

/** Returns { relativePath: content } for every generated Apps Script file. */
export function generateAppsScriptFiles() {
  const entries = Object.entries(CID_ASSETS).map(([cid, asset]) => {
    const base64 = readFileSync(join(ROOT, ASSET_DIR, asset.file)).toString("base64");
    return [
      `  ${cid}: {`,
      `    mimeType: '${asset.mimeType}',`,
      `    filename: '${mimeFilename(asset.file)}',`,
      `    // ${ASSET_DIR}/${asset.file}`,
      `    base64: '${base64}',`,
      `  },`,
    ].join("\n");
  });

  const assetsGs = `/**
 * GENERATED by emails/scripts/build-apps-script.mjs — do not edit by hand.
 *
 * The email's inline images, keyed by their LOCKED Content-ID (the HTML uses
 * src="cid:<key>"). Code.gs turns each entry into a Blob and attaches it as a
 * CID inline MIME part. Source PNGs: ${ASSET_DIR}/ (rendered from the
 * canonical JG Logo System v1.0 geometry and emails/src/icons/).
 */
const JG_EMAIL_ASSETS = Object.freeze({
${entries.join("\n")}
});
`;

  return {
    [`${APPS_SCRIPT_DIR}/Assets.gs`]: assetsGs,
    [`${APPS_SCRIPT_DIR}/JGIntroductionV2.html`]: readFileSync(join(ROOT, "emails/jg-introduction-v2.html"), "utf8"),
    [`${APPS_SCRIPT_DIR}/JGIntroductionV2Text.html`]: readFileSync(join(ROOT, "emails/jg-introduction-v2.txt"), "utf8"),
  };
}

const isMain = process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  for (const [path, content] of Object.entries(generateAppsScriptFiles())) {
    writeFileSync(join(ROOT, path), content);
    console.log(`  ${path} (${(Buffer.byteLength(content) / 1024).toFixed(1)} KB)`);
  }
}
